{
  "book_code": "4BAR",
  "verses": [
    {
      "chapter": 6,
      "verse": 1,
      "text_ar": "بعد ذلك، خرج أبيمليك من المدينة وصلى إلى الرب."
    },
    {
      "chapter": 6,
      "verse": 2,
      "text_ar": "فجاء ملاك الرب وأمسكه بيده اليمنى وأعاد به إلى حيث كان باروخ يجلس، فوجدَه في قبر."
    },
    {
      "chapter": 6,
      "verse": 3,
      "text_ar": "وعندما رأوا بعضهما البعض، بكى كلٌّ منهما وقبل الآخر."
    },
    {
      "chapter": 6,
      "verse": 4,
      "text_ar": "ولكن عندما رفع باروخ نظره، رأى بأم عينه التين المغطى في سلة أبيمليك."
    },
    {
      "chapter": 6,
      "verse": 5,
      "text_ar": "ورافعاً نظره إلى السماء، صلّى قائلاً:"
    }
  ]
}
